this.q=s=>this.shadowRoot.querySelector(s);this.cards=[...this.shadowRoot.querySelectorAll('.card')];this.stage=this.q('.stage');this.track=this.q('.track');this.left=this.q('.left');this.nav=this.q('.nav');this.update();
