const zoom=this.zoom,details=clamp((zoom-.6)/.38),intro=clamp(1-zoom*2.5);this.stage.style.setProperty('--details',details);this.stage.style.setProperty('--intro',intro);this.stage.style.setProperty('--bar',zoom);this.stage.toggleAttribute('data-expanded',zoom>.12);this.stage.style.setProperty('--progress',(p*100)+'%');this.left.classList.toggle('ready',details>.01);this.left.inert=details<.7;this.nav.classList.toggle('ready',details>.01);this.nav.inert=details<.7;this.q('.intro-meta').inert=intro<.5;this.q('.teaser').inert=intro<.5;this.q('.intro-meta').style.visibility=intro===0?'hidden':'visible';this.q('.teaser').style.visibility=intro===0?'hidden':'visible';
const cw=w*(mobile?.90:.59),ch=mobile?Math.min(h*.26,cw*.58):Math.min(h*.54,cw*.53);const radius=Math.max(w*2.2,h*2.5),step=(ch+cw*.20+72)/radius;const ax=w*(mobile?.50:.665),ay=h*(mobile?.73:.48);
